  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'daikokucho_direct', 'AME29 Nail (ban)', null, null, true, '¥8.200–16.980 (art), ¥9.890–11.980 (gói chip 120'')', '¥8,200〜16,980（アート）、¥9,890〜11,980（チップ120分コース）', 0) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 5.0, 102, '5.0★ / 102 review', '5.0★／口コミ102件', 'Rating tuyệt đối 5.0, review đều đặn từ khách quốc tế khen ''walk-in friendly'', đặt lịch qua website/Instagram dễ dàng.', '評価は満点の5.0。外国人観光客から「walk-in（予約なし）でも対応が親切」と高評価。ウェブサイト／Instagramからの予約がしやすいとの声も多い。', 'https://www.google.com/maps/search/?api=1&query=AME29+Nail+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, '93 review, 472 blog, 27 coupon', '口コミ93件、ブログ472件、クーポン27件', 'Menu 23 món. 4 nhân viên (3 ghế foot/hand). Coupon nổi bật: ''Chip dài+Art không giới hạn ¥13.980→¥11.980'', ''Art+Parts không giới hạn ¥10.980→¥9.890'', gói cọc tiền mặt ¥10.490/120 phút. Đăng blog rất đều (472 bài) — mạnh nhất nhóm.', 'メニュー23種。スタッフ4名（ハンド・フット計3席）。人気クーポン：「チップ長さだし＋アートし放題 ¥13,980→¥11,980」「アート＋パーツつけ放題 ¥10,980→¥9,890」、現金限定120分コース¥10,490。ブログ更新数472件はグループ内で最多。', 'https://beauty.hotpepper.jp/kr/slnH000783808/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '508 followers / 217 bài', 'フォロワー508人／投稿217件', 'Bio: giá niêm yết ¥8.000-10.000, nhận đặt lịch trong ngày. Định vị ''Korean nail, đơn giản sang trọng''.', 'プロフィールに料金¥8,000〜10,000を明記、当日予約可。「韓国ネイル・シンプルで上品」というポジショニング。', 'https://www.instagram.com/ame29_nail.osaka/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'tiktok', null, null, 'Có tài khoản riêng', '専用アカウントあり', '@ame29nailosaka — kênh chưa khai thác mạnh, là cơ hội để khác biệt hoá so với đối thủ (N2/Nem chỉ dùng TikTok để tuyển dụng).', '@ame29nailosaka — まだ十分に活用されていないチャネル。N2やNemはTikTokを採用活動にしか使っていないため、集客用に本格活用すれば差別化のチャンスになる。', 'https://www.tiktok.com/@ame29nailosaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'naily', null, null, 'Có mặt, coupon giảm 15%', '掲載あり、15%オフクーポン', 'Xác nhận có trang trên Naily (nailie.jp) — coupon ''Chip dài + Stone không giới hạn'' ¥12.980 (giảm 15%). Naily là app đặt lịch dựa trên chọn mẫu thiết kế trước, nổi bật với 3,23 triệu người theo dõi Instagram của chính app.', 'Nailie（nailie.jp）に掲載確認 — 「チップ長さだし＋ストーンやり放題」¥12,980（15%オフ）クーポンあり。Nailieはデザイン画像から直接予約するアプリで、公式Instagramは323万人フォロワーを持つ。', 'https://nailie.jp/beautist/cBAi1gACKj/posts/ngaADqKx77') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'daikokucho_direct', 'N2nail & academy', null, null, false, '¥4.500–6.800', '¥4,500〜6,800', 1) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.9, 125, '4.9★ / 125 review', '4.9★／口コミ125件', 'Review khen nhân viên thân thiện, giải thích giá kỹ, vị trí tầng 6 hơi khó tìm nhưng có hướng dẫn rõ.', 'スタッフが親切で料金説明も丁寧という口コミが多い。6階にあり少し分かりにくいが案内は明確。', 'https://www.google.com/maps/search/?api=1&query=N2nail+academy+Daikokucho+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, '20 review, mở 8:30–24:00', '口コミ20件、営業時間8:30〜24:00', 'Nailist nam, 10+ năm kinh nghiệm. Menu: One-color ¥4.500, Magnet/French/Gradient/Mirror/Matte ¥5.200, gói art 4 món cố định ¥6.200. Giờ mở dài nhất khu (đến nửa đêm).', '男性ネイリスト、経験10年以上。メニュー：ワンカラー¥4,500、マグネット／フレンチ／グラデーション／ミラー／マット¥5,200、定額アート4本コース¥6,200。エリア内で最も営業時間が長い（深夜0時まで）。', 'https://beauty.hotpepper.jp/g-nail/stc2200465/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '@n2.nail_daikokucho', '@n2.nail_daikokucho', 'Nội dung chủ yếu là mẫu nail đơn giản, tông ''うるつや'' (bóng mượt tự nhiên).', '投稿はシンプルなデザインが中心。「うるつやネイル」という自然な艶感を打ち出している。', 'https://www.instagram.com/n2.nail_daikokucho/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'tiktok', null, null, 'Có, dùng để tuyển dụng', 'あり（採用目的が中心）', 'Hashtag #n2nails chủ yếu xuất hiện trong video tuyển thợ/tuyển mẫu nail, không phải nội dung bán hàng.', '#n2nailsのハッシュタグはスタッフ募集・モデル募集の動画が中心で、集客用コンテンツではない。', null) on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'minimo', null, null, 'Có trên Minimo', 'Minimoに掲載あり', 'Từng xuất hiện trong danh sách Minimo khu Daikokucho, giá tương đồng Hotpepper.', '大国町エリアのMinimo一覧にも掲載されており、料金はHotpepperとほぼ同じ。', null) on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'naily', null, null, 'Có trang riêng', '専用ページあり', 'Xác nhận có mặt trên Naily, đăng thường xuyên mẫu ''uru-tsuya'' (bóng mượt tự nhiên), giờ mở 9:00-23:00.', 'Nailieに掲載確認、「うるつやネイル」デザインを定期投稿、営業時間9:00〜23:00。', 'https://nailie.jp/beautist/ZwMslSM3cg') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'daikokucho_direct', 'ChunChun nail salon', null, null, false, '¥3.900–4.000 (KH mới, gốc ~¥6.900)', '¥3,900〜4,000（新規、通常価格は約¥6,900）', 2) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.9, 99, '4.9★ / 99 review', '4.9★／口コミ99件', 'Rất nhiều review từ khách du lịch quốc tế, khen phản hồi Instagram nhanh, giá phải chăng.', '海外旅行者からの口コミが非常に多く、Instagramの返信が早い、価格が手頃という評価。', 'https://www.google.com/maps/search/?api=1&query=ChunChun+nail+salon+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, '4.9★ / 64-66 review', '4.9★／口コミ64〜66件', '2 nhân viên, mở đến 21h30-22h. Coupon: One-color (hand, gồm off) ¥4.300→¥4.000 (2 màu mix OK). Gói art 4 món 90 phút ¥6.900. Nhóm ''gần AME29'' theo Hotpepper: N2, Nem, AME29, Lotus.', 'スタッフ2名、営業時間は21:30〜22:00まで。クーポン：ワンカラー（オフ込み）¥4,300→¥4,000（2色ミックス可）、アート4本90分¥6,900。Hotpepper上の「近隣サロン」にはN2、Nem、AME29、Lotusが並ぶ。', 'https://beauty.hotpepper.jp/kr/slnH000702174/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '1.236 followers / 303 bài — mạnh nhất nhóm', 'フォロワー1,236人／投稿303件 — グループ内で最強', '@chunchun.nail_osaka — bio ghi rõ ''English speakers available'', nhận DM đặt lịch, hashtag địa phương #daikokucho #namba.', '@chunchun.nail_osaka — プロフィールに「English speakers available」と明記、DM予約対応、#daikokucho #namba など地域ハッシュタグを活用。', 'https://www.instagram.com/chunchun.nail_osaka/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'tiktok', null, null, 'VIRAL QUỐC TẾ — 1 video 548.500 lượt thích', '国際的にバズる — 1動画54.85万いいね', 'Một du khách nước ngoài (@millylivin) đăng video trải nghiệm tại ChunChun với tiêu đề ''tiệm nail rẻ nhất tôi tìm được ở Nhật'' — đạt 548.500 lượt thích, 1.603 bình luận. Video khen chủ tiệm (bắt đầu làm nail chỉ để giúp vợ) và nhắc đến rating Google 5 sao. Đây là nguồn traffic quốc tế lớn nhất trong toàn bộ dữ liệu, đến từ nội dung của khách chứ không phải tự đăng.', '外国人旅行者（@millylivin）が投稿した来店動画『日本で見つけた一番安いネイルサロン』が54.85万いいね・1,603コメントを獲得。オーナー（元々は妻を助けるためにネイル業を始めた）を称賛し、Google評価5つ星にも言及。全データ中最大級の国際的トラフィック源であり、自店投稿ではなく客側のコンテンツから生まれた点が特徴的。', 'https://www.tiktok.com/@chunchun.nail.osa') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'daikokucho_direct', 'Bibi Beauty Spa Osaka', null, null, false, '¥3.500 one-color', 'ワンカラー¥3,500', 3) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 5.0, 35, '5.0★ / 35 review', '5.0★／口コミ35件', 'Khách khen nhân viên nước ngoài (Việt Nam) nhiệt tình, mi kéo dài lâu, không gian thư giãn.', 'ベトナム人スタッフの対応が親身、まつげエクステの持ちが良い、リラックスできる空間という口コミ。', 'https://www.google.com/maps/search/?api=1&query=Bibi+Beauty+Spa+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, '4.79★ / 89 review', '4.79★／口コミ89件', 'One-color từ ¥3.500 — rẻ nhất nhóm 6 tiệm. Nhóm ''gần Bibi'' theo Hotpepper: Lacus, Lotus, ANGEL, Nail de Mafi, AME29.', 'ワンカラー¥3,500〜と6サロン中最安値。Hotpepperの「近隣サロン」はLacus、Lotus、ANGEL、Nail de Mafi、AME29。', 'https://beauty.hotpepper.jp/kr/slnH000739040/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '225 followers / 601 bài', 'フォロワー225人／投稿601件', '@bibi_nailsalon — follower thấp nhưng đăng bài cực đều (601 bài), thiên về giữ chân khách cũ hơn là thu hút khách mới.', '@bibi_nailsalon — フォロワーは少ないが投稿頻度は非常に高い（601件）。新規獲得よりリピーター維持を重視した運用と見られる。', 'https://www.instagram.com/bibi_nailsalon/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'tiktok', null, null, 'Không rõ', '不明', 'Không tìm thấy TikTok riêng; có trang Facebook 723 lượt thích thay thế.', '専用TikTokは見つからず。代わりにFacebookページ（723いいね）を運用。', null) on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'daikokucho_direct', 'Nem nailstudio (NEM.)', null, null, false, 'Định vị ''nhanh - rẻ - đơn giản đến art cá tính''', '「速い・安い・シンプルから個性派アートまで」のポジショニング', 4) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 5.0, 30, '5.0★ / 30 review', '5.0★／口コミ30件', 'Khách khen chủ tiệm là người Việt Nam, kiên nhẫn với khách nước ngoài dù rào cản ngôn ngữ.', 'ベトナム人オーナーが言語の壁があっても外国人客に辛抱強く対応してくれると評判。', 'https://www.google.com/maps/search/?api=1&query=Nem+nailstudio+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, '4.94★ / 69 review — cao nhất nhóm', '4.94★／口コミ69件 — グループ内最高評価', 'Định vị ''mới mở, 3 năm kinh nghiệm, tốc độ nhanh - giá rẻ - từ đơn giản đến art cá tính''. Rating trung bình cao nhất trong toàn bộ nhóm 6 tiệm.', '「新規オープン、経験3年、速さ・安さ・シンプルから個性派アートまで対応」というアピール。6サロン中で平均評価が最も高い。', 'https://beauty.hotpepper.jp/kr/slnH000702159/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '@nem.nailstudio', '@nem.nailstudio', 'Nội dung mẫu nail đa dạng, từ đơn giản đến art phức tạp.', 'シンプルなものから凝ったアートまで幅広いデザインを投稿。', 'https://www.instagram.com/nem.nailstudio/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'tiktok', null, null, 'SỬA LẠI: hướng khách hàng cộng đồng Việt', '訂正：ベトナム人コミュニティ向け集客', 'Đính chính: TikTok @nem.nailstudio thực ra target trực tiếp cộng đồng người Việt tại Nhật qua hashtag #tiemnailviettainhat #nailviettainhat — không chỉ tuyển dụng như nhận định trước. Đây là chiến lược nhắm đúng ngách khách hàng đồng hương rất rõ ràng.', '訂正：TikTok @nem.nailstudioは実際には#tiemnailviettainhat #nailviettainhatのハッシュタグで在日ベトナム人コミュニティを直接ターゲットにしている — 採用目的だけではなかった。同郷客というニッチを明確に狙う戦略。', 'https://www.tiktok.com/@nem.nailstudio') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'naily', null, null, 'Tiệm tại nhà, 51 đánh giá', '自宅サロン、評価51件', 'Phát hiện quan trọng: đây là ''tiệm nail tại nhà'' (không phải cửa hàng mặt tiền), chủ người Việt nói được tiếng Nhật, nhận thiết kế mang theo, cho nam giới, gần bãi đậu xe.', '重要な発見：「自宅ネイルサロン」（路面店ではない）、ベトナム人オーナーは日本語対応可、持ち込みデザイン歓迎、メンズ可、駐車場多数近隣。', 'https://nailie.jp/beautist/bNFfh3h6UW') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
