  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.7, 27, '4.7★ / 27 review', '4.7★／口コミ27件', 'Khách khen không gian sạch sẽ, nhiều màu/parts để chọn, nhân viên vui vẻ.', '清潔感のある空間、豊富なカラー・パーツ、スタッフの明るい対応が高評価。', 'https://www.google.com/maps/search/?api=1&query=Nail+salon+ANGEL+Daikokucho+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, '500+ màu/phụ kiện', 'カラー・パーツ500種類以上', 'Mở đến 21h. USP rõ ràng: có dịch vụ đồ uống bao gồm cả rượu — tạo trải nghiệm thư giãn khác biệt so với các tiệm còn lại.', '21時まで営業。お酒を含むドリンクサービスが明確な差別化ポイントで、他店にはないリラックス体験を提供。', 'https://beauty.hotpepper.jp/kr/slnH000735062/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, 'Tên đầy đủ: ''Mai Nailsalon. ANGEL''', '正式名称：「Mai Nailsalon. ANGEL」', 'Xác nhận tên đầy đủ và chủ tiệm tên Mai, địa chỉ khớp đúng Shikitsunishi (Naniwa-ku) gần Daikokucho. Chưa lấy được handle Instagram chính xác qua tìm kiếm.', '正式名称とオーナー名（Mai）を確認、住所は大国町近くの敷津西（浪速区）と一致。検索では正確なInstagramハンドルまでは特定できず。', null) on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
