  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, 'Coupon khách mới nhiều đợt', '新規向けクーポン多数', 'One-color/gradient ¥3.900-4.500 (giới hạn số lượng khách mới theo mùa), art không giới hạn 2 món ¥4.600, 10 món ¥7.300 (đã gồm off).', 'ワンカラー／グラデーション¥3,900〜4,500（季節ごとの新規限定人数あり）、アート2本し放題¥4,600、10本¥7,300（オフ込み）。', 'https://beauty.hotpepper.jp/genre/kgkw029/stc2202875/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
