  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'osaka_top', 'Nail salon Diva Shinsaibashi grace', null, null, false, 'One-color ¥4.510 (đã gồm off+care)', 'ワンカラー¥4,510（オフ・ケア込み）', 0) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.8, 1325, '4.8★ / 1.325 review', '4.8★／口コミ1,325件', 'Chuỗi Diva thành lập 2001, 15 chi nhánh Tokyo/Osaka.', 'Diva（2001年創業）は東京・大阪に15店舗展開。', 'https://www.google.com/maps/search/?api=1&query=Nail+salon+Diva+Shinsaibashi+grace') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, '4.59★ / 453 review', '4.59★／口コミ453件', 'Công nghệ độc quyền ''Repeat Beauty Gel'' giữ nguyên gel cũ, chỉ phủ lớp mới — giảm tổn thương móng. One-color ¥4.510 (off+care). Mở 10:00-19:00 (nhận khách cuối 18:00-19:00).', '特許技術「リピートビューティージェル」で前回のベースを残し新しいジェルを重ねる独自技法。ワンカラー¥4,510（オフ・ケア込み）。営業10:00〜19:00最終受付。', 'https://beauty.hotpepper.jp/kr/slnH000316523/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '@nailsalondiva_official (13.000 followers, 2.127 bài)', '@nailsalondiva_official（13,000人・2,127投稿）', 'Thương hiệu Diva dùng 1 tài khoản Instagram chung toàn chuỗi (13.000 followers) thay vì từng chi nhánh riêng — khác với mô hình ''mỗi chi nhánh 1 tài khoản'' của ChunChun/AME29. Xác nhận có 15 chi nhánh (không phải 14) khắp Tokyo/Kanagawa/Osaka/Hyogo/Nara.', 'Divaは支店ごとではなくブランド共通の1アカウント（13,000人）で運用 — ChunChun／AME29のような「支店ごとに個別アカウント」モデルとは異なる。全国15店舗（14店舗ではなく）を東京・神奈川・大阪・兵庫・奈良に展開と確認。', 'https://www.instagram.com/nailsalondiva_official/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'tiktok', null, null, 'Xác nhận CHÍNH THỨC là tài khoản tuyển dụng', '公式に「採用アカウント」と明記', 'Trang web chính thức của Diva ghi rõ TikTok là ''採用アカウント'' (tài khoản tuyển dụng) — xác nhận trực tiếp từ nguồn chính chủ, không phải suy đoán. Đây là bằng chứng rõ ràng nhất trong toàn bộ dữ liệu về việc 1 chuỗi lớn chủ động KHÔNG dùng TikTok để bán hàng.', 'Diva公式サイトで「TikTok 採用アカウント」と明記 — 推測ではなく一次情報での確認。大手チェーンが意図的にTikTokを集客に使わないという、全データ中最も明確な証拠。', null) on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
