  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, '4.79★ / 244 review — ĐÃ ĐỔI THƯƠNG HIỆU', '4.79★／口コミ244件 — ブランド刷新済み', '⚡ CẬP NHẬT QUAN TRỌNG: ''I-nails Shinsaibashi'' đã đóng cửa ngày 31/3/2026 và tái khởi động thành thương hiệu mới ''Jemiy nail'' từ 1/6/2026 (cùng địa chỉ, cùng nhóm ''Inails group'', chỉ đổi tên+nâng cấp không gian). Đây là đối thủ xuất hiện gần như MỌI từ khóa tìm kiếm trong công cụ MEO-dash của bạn — cực kỳ mạnh về SEO Google Maps.', '⚡重要更新：「I-nails心斎橋店」は2026年3月31日に閉店し、2026年6月1日より新ブランド「Jemiy nail」として再スタート（同住所・同じInailsグループ、名称と内装のみ刷新）。MEO-dashのほぼすべての検索キーワードに登場する、Googleマップ検索SEOで最も強い競合の一つ。', 'https://beauty.hotpepper.jp/kr/slnH000439202/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '@jemiy_nail (thương hiệu chung, 15.000 followers)', '@jemiy_nail（ブランド共通、15,000人）', 'Tài khoản Instagram chung cho cả chuỗi Jemiy nail (có cả chi nhánh Ebisu, Shinjuku Tokyo) — 15.000 followers, 697 bài. Đây là con số Instagram CAO THỨ 2 trong toàn bộ dữ liệu, chỉ sau Care & Spa Lovin Nails (5.616... khoan, Jemiy còn cao hơn!). Thực ra đây là followers cao NHẤT ghi nhận được.', 'Jemiy nailチェーン共通アカウント（東京・恵比寿/新宿店も含む）— フォロワー15,000人、投稿697件。全データ中で確認できた最多のInstagramフォロワー数。', 'https://www.instagram.com/jemiy_nail/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
