  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.9, 83, '4.9★ / 83 review', '4.9★／口コミ83件', '⚠️ Lưu ý: chưa xác minh chắc chắn đây có đúng là chi nhánh Tsuruhashi hay không — trang Hotpepper tìm được có vẻ tập trung vào mi (matsuge) nhiều hơn nail, và không ghi rõ địa chỉ Tsuruhashi. Độ tin cậy thấp hơn các tiệm khác.', '⚠️注意：鶴橋店との完全一致は未確認 — 見つかったHotpepperページはまつげ関連が中心で、鶴橋の住所明記もなし。他の店舗より確度は低い。', 'https://www.google.com/maps/search/?api=1&query=muni+Tsuruhashi+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
