  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, 'SNS chuỗi hơn 10.000 followers', 'ブランドSNSフォロワー1万人超', 'Mở 10:00-19:30 (nhận cuối 18:00). Có hệ thống ''Diva Award'' vinh danh nailist xuất sắc hàng năm — tạo động lực nội bộ.', '営業10:00〜19:30（最終受付18:00）。優秀ネイリストを毎年表彰する「Divaアワード」制度あり — 社内のモチベーション向上策。', 'https://beauty.hotpepper.jp/kr/slnH000140780/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
