  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 5.0, 75, '5.0★ / 75 review', '5.0★／口コミ75件', '⚠️ Lưu ý: đây là salon làm đẹp phong cách Hàn Quốc tổng hợp (trang điểm, mi, chân mày, esthetic) — nail chỉ là 1 trong nhiều dịch vụ, chỉ có 1 nhân viên chuyên nail trong tổng 4 người.', '⚠️注意：韓国style総合美容サロン（メイク・まつげ・眉毛・エステ）— ネイルはサービスの一部で、スタッフ4人中ネイル専門は1人のみ。', 'https://www.google.com/maps/search/?api=1&query=beauty+salon+onni+Juso+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
