  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 3.5, 184, '3.5★ / 184 review', '3.5★／口コミ184件', 'Chuỗi NICENAIL (100+ chi nhánh), tự khảo sát nội bộ ''4.4/5 điểm, 80% muốn quay lại'' — nhưng rating Google thấp hơn hẳn (3.5) so với khảo sát riêng, đáng chú ý sự chênh lệch.', 'NICENAILチェーン（100店舗以上）、自社アンケートでは「4.4/5、80%が再利用したい」と発表 — しかしGoogle評価は3.5と大きく低く、この乖離は注目に値する。', 'https://www.google.com/maps/search/?api=1&query=Nice+nail+Umeda+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
