  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.4, 100, '4.4★ / 100 review', '4.4★／口コミ100件', 'Cùng chuỗi NICENAIL, gần ga Hankyu Ibaraki 2-3 phút, chuyên nail đơn giản nhưng vẫn nhận art/trend.', 'NICENAILチェーン、阪急茨木市駅徒歩2〜3分、シンプルネイル中心だがトレンドアートにも対応。', 'https://www.google.com/maps/search/?api=1&query=Nice+Nail+Hankyu+Ibaraki+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, 'Tiêu chuẩn đồng nhất toàn chuỗi', '全店統一基準', 'Nhấn mạnh ''tiêu chuẩn dịch vụ đồng nhất toàn quốc, nhân viên qua đào tạo chung'' — khác với tiệm độc lập, cạnh tranh bằng tính nhất quán/dự đoán được.', '「全国統一の研修カリキュラム、均質なサービス品質」を強調 — 独立系サロンとは異なり、一貫性・予測可能性で勝負。', 'https://www.nice-nail.com/salon/kansai/ibaraki/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
