  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.5, 115, '4.5★ / 115 review', '4.5★／口コミ115件', 'Chuyên nối dài + nail 3D, 500 màu, tại Motomachi (Naniwa-ku), gần ga JR Namba 1 phút / ga Namba 3 phút.', '長さ出し＋3Dネイル専門、カラー500色、元町（浪速区）、JR難波駅徒歩1分／なんば駅徒歩3分。', 'https://www.google.com/maps/search/?api=1&query=Nova+Nail+Namba+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, 'Coupon rõ ràng, 107 lượt cập nhật', 'クーポン明記、更新107件', '10 móng nối dài+art không giới hạn ¥11.500 (phổ biến #1); mang thiết kế riêng 90 phút art không giới hạn ¥8.900 (gốc ¥10.900); gói 6 móng art+nối dài ¥9.200.', '10本長さ出し＋アートし放題¥11,500（人気No.1）；持ち込み90分アートし放題¥8,900（通常¥10,900）；6本アート＋長さ出し¥9,200。', 'https://beauty.hotpepper.jp/kr/slnH000731835/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '@nova.nail.osaka', '@nova.nail.osaka', 'Tài khoản chính, đăng mẫu nail dài/3D thường xuyên.', 'メインアカウント、ロングネイル／3Dデザインを定期的に投稿。', 'https://www.instagram.com/nova.nail.osaka/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'minimo', null, null, 'Có trang riêng', '専用ページあり', 'Đăng nhiều hashtag #スカルプネイル #ロングネイル #ストーンネイル, chuyên biệt hoá rõ ràng vào nối dài/đá đính.', '#スカルプネイル #ロングネイル #ストーンネイル等のハッシュタグ多数、長さ出し・ストーンに明確特化。', 'https://minimodel.jp/salon/29a35e1622adc844b998c4950d081fa8') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'naily', null, null, 'Có, dịch vụ trà miễn phí + coupon ¥500 cho KH quay lại', 'あり、無料お茶サービス＋リピーター¥500クーポン', 'Xác nhận là tiệm nổi bật trên Naily: mô tả rõ chính sách trễ giờ >15 phút bị coi là đổi/huỷ lịch, có thể phát sinh phí huỷ. Một bài đăng Facebook công khai thừa nhận từng hoàn 100% tiền cho khách vì thiếu chú ý — hiếm thấy sự minh bạch này.', 'Nailieで目立つサロインと確認：15分以上の遅刻はメニュー変更・キャンセル扱いとなり得ると明記。Facebookの投稿では、注意不足で全額返金した経験を公表 — 珍しい透明性。', 'https://nailie.jp/beautist/gHC0tqZuP4') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'osaka_top', '7.Nail Salon', null, null, false, 'Chưa xác nhận giá cụ thể', '具体的な料金は未確認', 43) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.8, 92, '4.8★ / 92 review', '4.8★／口コミ92件', '⚡ Xuất hiện trong GẦN NHƯ MỌI từ khóa tìm kiếm theo công cụ MEO-dash của AME29 — đây là 1 trong những đối thủ SEO Google Maps mạnh nhất khu vực Naniwa-ku.', '⚡AME29のMEO-dashツールで、ほぼすべての検索キーワードに登場 — 浪速区エリアで最もGoogleマップSEOが強い競合の一つ。', 'https://www.google.com/maps/search/?api=1&query=7+Nail+Salon+Namba+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, 'Tên thật: ''ナナネイル(7.Nail)''', '正式名称：「ナナネイル(7.Nail)」', 'Tên hiển thị Google Maps ''7.Nail Salon'' thực ra là ''ナナネイル'' (Nana Nail, đọc số 7 kiểu Nhật ''nana'') trên Hotpepper — dễ gây nhầm với tiệm ''Nana Nail'' khác đã có trong dữ liệu.', 'Googleマップ表示名「7.Nail Salon」はHotpepper上では実際「ナナネイル」（7＝ななと読む）— データ内の別の「Nana Nail」と混同しやすい点に注意。', 'https://beauty.hotpepper.jp/kr/slnH000497017/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'osaka_top', 'SALON DOUDOU', null, null, false, 'Định giá ¥6.800-8.800/tháng (mẫu đổi mới hàng tháng)', '月替わり定額¥6,800〜8,800', 44) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', null, null, 'Xuất hiện liên tục trong MEO-dash', 'MEO-dashに継続的に登場', '⚡ Xuất hiện trong hầu hết từ khóa tìm kiếm của AME29 (nail salon near me, nail near me, manicure & pedicure salon near me) — đối thủ SEO rất mạnh.', '⚡AME29のほぼすべての検索キーワード（nail salon near me、nail near me、manicure & pedicure salon near me）に登場 — SEOの強い競合。', 'https://www.google.com/maps/search/?api=1&query=SALON+DOUDOU+Osaka') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, '1.496 blog, 102 review', 'ブログ1,496件、口コミ102件', 'Mô hình kết hợp nail + esthetic da mặt kiểu Hàn (lột da, trị mụn) + mi — không chỉ chuyên nail. Định giá ''DOUDOU ワンホン'' đổi mẫu hàng tháng ¥6.800-8.800. Số blog 1.496 thuộc top cao nhất dữ liệu.', 'ネイル＋韓国式フェイシャルエステ（ピーリング、ニキビケア）＋まつげの複合モデル — ネイル専門ではない。月替わり「DOUDOUワンホンコース」¥6,800〜8,800。ブログ数1,496件はデータ内トップクラス。', 'https://beauty.hotpepper.jp/kr/slnH000494553/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
