  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'national_top', 'la vela tokyo', null, 'Tokyo-Ginza', false, '¥9.350–10.890 (kể cả gói khách mới, không giảm sâu)', '¥9,350〜10,890（新規客向けメニューも含め、大幅値引きはしない）', 8) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.9, 528, '4.9★ / 528 review', '4.9★／口コミ528件', 'Rating rất cao dù giá thuộc top cao nhất trong toàn bộ dữ liệu quốc gia.', '全国データの中でも価格帯はトップクラスに高いにもかかわらず、評価は非常に高い。', 'https://www.google.com/maps/search/?api=1&query=la+vela+tokyo+Ginza') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, 'Coupon ''khách mới'' vẫn giữ giá cao', '「新規」クーポンも高価格を維持', 'One-color trải nghiệm ¥9.350 (90 phút, chỉ áp dụng nếu đặt trước 19h). Gói nuance design khách mới ¥10.890 kèm tặng găng tay dưỡng da khi để lại review. Phí hủy cùng ngày ¥5.500. Off tại tiệm ¥2.200 vs off tiệm khác ¥6.050.', 'お試しワンカラー¥9,350（90分、19時までの予約限定）。新規限定ニュアンスデザイン¥10,890、口コミ投稿でハンドケア用ミトンをプレゼント。当日キャンセル料¥5,500。自店オフ¥2,200 vs 他店オフ¥6,050と大きく差をつけている。', 'https://beauty.hotpepper.jp/kr/slnH000549844/coupon/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '@lavela_tokyo', '@lavela_tokyo', 'Định vị ''đại nhân ニュアンスネイル'', không gian như khách sạn, nến thơm, nhạc thư giãn.', '「大人ニュアンスネイル」というポジショニング。ホテルライクな空間、キャンドル、ヒーリングミュージックが特徴。', 'https://www.instagram.com/lavela_tokyo/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'national_top', 'Nail salon Diva Ginza', null, 'Tokyo-Ginza', false, 'One-color từ ¥5.060 (60 phút)', 'ワンカラー¥5,060〜（60分）', 9) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 4.8, 504, '4.8★ / 504 review', '4.8★／口コミ504件', 'Chuỗi toàn quốc (Tokyo/Kanagawa/Osaka/Hyogo), 25 năm, công nghệ độc quyền Lipi-gel.', '全国チェーン（東京／神奈川／大阪／兵庫）、創業25年、独自技術「リピジェル」が特徴。', 'https://www.google.com/maps/search/?api=1&query=Nail+salon+Diva+Ginza') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, 'Định vị ''60 phút xong việc''', '「60分完結」というポジショニング', 'One-color (off+care gồm) ¥5.060-7.700. Không chạy giá rẻ, giữ định vị dưỡng móng lâu bền dù là chuỗi.', 'ワンカラー（オフ・ケア込み）¥5,060〜7,700。チェーン店でありながら値引き競争はせず、「爪育」による長持ちを訴求。', 'https://beauty.hotpepper.jp/kr/slnH000255231/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, 'Chưa xác nhận riêng chi nhánh Ginza', '銀座店単独のアカウントは未確認', 'Thương hiệu Diva có Instagram chung toàn chuỗi.', 'Divaブランド全体で共通のInstagramを運用。', null) on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'tiktok', null, null, 'Có tài khoản tuyển dụng toàn chuỗi', 'チェーン共通の採用アカウントあり', 'Dùng chủ yếu cho tuyển dụng nhân sự, không phải bán hàng.', '主に採用活動に使われており、集客用ではない。', null) on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitors (business_unit_id, group_key, name, area, city, is_ame29, price_vi, price_ja, sort_order) values (v_bu_id, 'national_top', 'Friday 21 Nail Salon', null, 'Osaka-Shinsaibashi', false, '¥2.850 (KH mới, gốc ¥6.900-7.500) — giá mồi sâu nhất đã ghi nhận', '¥2,850（新規、通常¥6,900〜7,500）— 確認できた中で最も大幅な導入価格', 0) on conflict (business_unit_id, group_key, name) do update set area = excluded.area, city = excluded.city, is_ame29 = excluded.is_ame29, price_vi = excluded.price_vi, price_ja = excluded.price_ja, sort_order = excluded.sort_order, updated_at = now() returning id into v_id;
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'gmaps', 5.0, 1871, '5.0★ / 1.871 review — cao nhất Osaka', '5.0★／口コミ1,871件 — 大阪で最多', 'Số review vượt trội mọi tiệm khác trong dữ liệu, chủ yếu nhờ chiến lược giá mồi cực sâu cho khách mới.', 'データ内の他店を大きく上回る口コミ数。新規客向けの大幅値引き戦略が主な要因と見られる。', 'https://www.google.com/maps/search/?api=1&query=Friday+21+Nail+Salon+Shinsaibashi') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'hotpepper', null, null, 'Trang Hotpepper chính thức', 'Hotpepper公式ページ', 'Xác nhận trực tiếp từ chủ tiệm (từng làm việc tại Mỹ, có bằng nail Mỹ). Có blog Hotpepper hoạt động đều.', 'オーナー本人が公式に案内（アメリカ勤務経験・米国ネイルライセンス保持）。Hotpepperブログも定期更新。', 'https://beauty.hotpepper.jp/kr/slnH000491935/') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
  insert into competitor_platform_stats (competitor_id, platform, rating, review_count, summary_vi, summary_ja, detail_vi, detail_ja, url) values (v_id, 'instagram', null, null, '@aikoueda_nail (7.252 followers, 2.881 bài)', '@aikoueda_nail（7,252人・2,881投稿）', 'Follower cao hơn nhiều so với ChunChun (1.236) trong dữ liệu Daikokucho — xác nhận Friday21 thực sự là 1 trong những tiệm độc lập mạnh nhất về Instagram trong toàn bộ Osaka. Chỉ nhận đặt lịch trước (appointments only).', '大国町エリアのChunChun（1,236人）を大きく上回るフォロワー数 — Friday21は大阪の独立系サロンの中でInstagram運用が最も強い部類に入ることを確認。完全予約制。', 'https://www.instagram.com/aikoueda_nail') on conflict (competitor_id, platform) do update set rating = excluded.rating, review_count = excluded.review_count, summary_vi = excluded.summary_vi, summary_ja = excluded.summary_ja, detail_vi = excluded.detail_vi, detail_ja = excluded.detail_ja, url = excluded.url, updated_at = now();
